/// <summary>
/// Method to count number of charges for a transaction
/// </summary>
/// <param name = "_transTableId">Transaction table id</param>
/// <param name = "_transRecId">Transaction record id</param>
/// <returns>Count of charges</returns>
public static int METCountCharges(MarkupTransRefTableId _transTableId, MarkupTransRefRecId _transRecId)
{
    return int642int((select count(RecId) from MarkupTrans
                               where MarkupTrans.transTableId == _transTableId
                                  && MarkupTrans.transRecId   == _transRecId).RecId);
}

/// <summary>
/// Bug 275352: CB411- Vendor auto charges not getting copied to sales lines (DIsc1 and Disc2) if created through CT
/// Method to make pending vendor invoice line off remit charge codes not editable
/// </summary>
/// <param name = "_hasVendorInvoice">A Boolean value indicating whether the misc. charge is connected to a purchase order invoice</param>
/// <param name = "_isCallerDatasourceEditable">A Boolean value indicating whether the calling datasource is editable</param>
/// <returns>true if the <c>MarkupTrans</c> record can be edited; otherwise, false.</returns>
boolean editingAllowed(boolean _hasVendorInvoice, boolean _isCallerDatasourceEditable)
{
    boolean editing = next editingAllowed(_hasVendorInvoice, _isCallerDatasourceEditable);

    if (editing
    &&  this.ModuleCategory == HeadingLine::Line
    &&  this.ModuleType     == MarkupModuleType::Vend
    &&  this.TransTableId   == tableNum(VendInvoiceInfoLine)
        &&  MarkupTable::find(this.ModuleType, this.MarkupCode).METIsOffRemittance)
    {
        editing = false;
    }

    return editing;
}
